def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """
    Check if in given list of numbers, are any two numbers closer to each other than
    given threshold.
    """
    for i in range(len(numbers)):
        for j in range(i+1, len(numbers)):
            if abs(numbers[i] - numbers[j]) < threshold:
                return True
    return False

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def find_topmost_carpet(n, carpets, point):
    for i in range(n):
        carpet = carpets[i]
        if carpet[0] <= point[0] < carpet[0] + carpet[2] and carpet[1] <= point[1] < carpet[1] + carpet[3]:
            return i
    return -1

def find_number_combinations() -> List[Tuple[int, int, int]]:
    """
    Generate all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing the
                        valid number combinations in ascending order based on the first number.
    """
    num_combinations = []
    for i in range(1, 9):
        for j in range(i, 9):
            for k in range(j, 9):
                if k % i == 0 and k // i == j:
                    num_combinations.append((i * 100 + j * 10 + k, i * 200 + j * 20 + k, i * 300 + j * 30 + k))
    return sorted(num_combinations)

def sum_of_factorials_optimized(n: int) -> int:
    if n < 1 or n > 50:
        raise ValueError("n must be between 1 and 50 inclusive")
    factorial = 1
    total = 0
    for num in range(1, n + 1):
        factorial *= num
        total += factorial
    return total

